// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.ReconciliationCase.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(reconciliationcase.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *ReconciliationCaseUpsertBulk) UpdateNewValues() *ReconciliationCaseUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(reconciliationcase.FieldID)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(reconciliationcase.FieldCreatedAt)
			}
			if _, exists := b.mutation.Provider(); exists {
				s.SetIgnore(reconciliationcase.FieldProvider)
			}
			if _, exists := b.mutation.Kind(); exists {
				s.SetIgnore(reconciliationcase.FieldKind)
			}
			if _, exists := b.mutation.Subject(); exists {
				s.SetIgnore(reconciliationcase.FieldSubject)
			}
			if _, exists := b.mutation.DedupeKey(); exists {
				s.SetIgnore(reconciliationcase.FieldDedupeKey)
			}
			if _, exists := b.mutation.ExpectedMinor(); exists {
				s.SetIgnore(reconciliationcase.FieldExpectedMinor)
			}
			if _, exists := b.mutation.ActualMinor(); exists {
				s.SetIgnore(reconciliationcase.FieldActualMinor)
			}
			if _, exists := b.mutation.Currency(); exists {
				s.SetIgnore(reconciliationcase.FieldCurrency)
			}
			if _, exists := b.mutation.Detail(); exists {
				s.SetIgnore(reconciliationcase.FieldDetail)
			}
		}
	}))
	return u
}

